import hashlib,json,os,stat
from pathlib import Path
m=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
base=Path(os.environ['STAMPED_JUDGE_TARGET']).parents[1] # operational/content; parent parents? workspace -> content->operational
# Correct content root is target's parent (workspace) then parent directory's parent
content=Path(os.environ['STAMPED_JUDGE_TARGET']).parent.parent
allowed={'content/workspace/.git/annex/keysdb/db','content/workspace/.git/annex/keysdb/db-shm','content/workspace/.git/annex/keysdb/db-wal'}
problems=[]; checked=0; meta=[]
for e in m['entries']:
    rel=e['path']
    if not rel.startswith('content/'): continue
    p=content/rel.removeprefix('content/')
    try: st=p.lstat()
    except FileNotFoundError:
        problems.append({'path':rel,'issue':'missing'}); continue
    kind='symlink' if stat.S_ISLNK(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'file' if stat.S_ISREG(st.st_mode) else 'other'
    if kind!=e['kind'] or stat.S_IMODE(st.st_mode)!=e['mode']:
        problems.append({'path':rel,'issue':'kind-or-mode','actual_kind':kind,'actual_mode':stat.S_IMODE(st.st_mode),'expected_kind':e['kind'],'expected_mode':e['mode']}); continue
    if kind=='file':
        h=hashlib.sha256()
        with p.open('rb') as f:
            for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
        if h.hexdigest()!=e.get('sha256') or st.st_size!=e.get('size'):
            if rel in allowed: meta.append(rel)
            else: problems.append({'path':rel,'issue':'content-mismatch','actual_sha256':h.hexdigest(),'expected_sha256':e.get('sha256')})
    elif kind=='symlink':
        h=hashlib.sha256(os.readlink(p).encode()).hexdigest()
        if os.readlink(p)!=e.get('link_target') or h!=e.get('sha256'):
            problems.append({'path':rel,'issue':'link-mismatch'})
    checked+=1
print(json.dumps({'entries_checked':checked,'mismatches':problems,'operational_metadata_changes':meta},indent=2))
